def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    k = 3  # Size of the sliding window
    rolling_max_list = []
    window = []

    for i, num in enumerate(numbers):
        if i >= k and window[0] == numbers[i - k]:
            window.pop(0)

        while window and window[-1] < num:
            window.pop()

        window.append(num)

        if i >= k - 1:
            rolling_max_list.append(window[0])

    return rolling_max_list

