def right_angle_triangle(a, b, c):
    # Validate input values to ensure they are positive integers
    if not all(isinstance(side, int) and side > 0 for side in [a, b, c]):
        return False

    # Check if the three sides can form a triangle by comparing the sum of any two sides with the third side
