    def count_sevens(num):
        return str(num).count('7')

    def is_divisible_by_11_or_13(num):
        return num % 11 == 0 or num % 13 == 0

    count = 0
    for i in range(1, n):
        if count_sevens(i) > 0 and is_divisible_by_11_or_13(i):
            count += 1

    return count

